// Package certificate defines the records of client certificates issued to
// users, which the users and the operators managing them may revoke.
package certificate

import (
	"errors"
	"fmt"
	"strings"
	"time"
)

// KeySource tells where the certificate's private key was created.
type KeySource string

// The key sources.
const (
	// KeySourceGenerated is a key generated by the server and downloaded once by the user.
	KeySourceGenerated KeySource = "generated"
	// KeySourceCSR is a key kept by the user, who sent a certificate signing request.
	KeySourceCSR KeySource = "csr"
	// KeySourceImported is the key of a certificate the CA signed outside this
	// application, which an access administrator imported so it can be revoked.
	KeySourceImported KeySource = "imported"
)

// MaxList bounds the number of certificates one list returns.
const MaxList = 200

var (
	// ErrNotFound is returned when there is no certificate with the given serial.
	ErrNotFound = errors.New("certificate not found")
	// ErrRevoked is returned when revoking a certificate that is already revoked.
	ErrRevoked = errors.New("certificate already revoked")
	// ErrNotStored is returned when a certificate was issued before its encoding was stored.
	ErrNotStored = errors.New("certificate not stored")
	// ErrExists is returned when creating a certificate whose serial is already recorded.
	ErrExists = errors.New("certificate already exists")
)

// Certificate is the record of one issued certificate.
type Certificate struct {
	// Serial is the lowercase hex serial number.
	Serial string `json:"serial"`
	// UserPK is the authentik primary key of the user the certificate is
	// issued to. It is 0, and Username is empty, for an imported certificate
	// assigned to no user (see Assigned).
	UserPK   int    `json:"user_pk"`
	Username string `json:"username"`
	// Subject is the certificate's subject distinguished name.
	Subject   string    `json:"subject"`
	NotBefore time.Time `json:"not_before"`
	NotAfter  time.Time `json:"not_after"`
	// IssuedAt is set by the store; for an imported certificate it is the time of the import.
	IssuedAt time.Time `json:"issued_at"`
	// IssuedBy is the username of the user who requested the certificate, or
	// of the access administrator who imported it.
	IssuedBy  string    `json:"issued_by"`
	KeySource KeySource `json:"key_source"`
	// RevokedAt is nil while the certificate is not revoked.
	RevokedAt *time.Time `json:"revoked_at"`
	// RevokedBy is the username of the revoking user; empty while not revoked.
	RevokedBy string `json:"revoked_by"`
	// DER is the encoded certificate, stored when it is created; lists leave it empty.
	DER []byte `json:"-"`
	// Stored is set when DER is stored, so the certificate can be downloaded.
	// Certificates issued before encodings were stored have none.
	Stored bool `json:"stored"`
}

// Assigned reports whether the certificate belongs to a user. Only imported
// certificates may belong to none; they can still be listed and revoked.
func (c Certificate) Assigned() bool {
	return c.UserPK != 0
}

// Status is the state of a certificate, for filtering lists.
type Status string

// The certificate states.
const (
	// StatusActive is a certificate that is neither revoked nor expired.
	StatusActive Status = "active"
	// StatusRevoked is a revoked certificate, expired or not.
	StatusRevoked Status = "revoked"
	// StatusExpired is a certificate that expired without being revoked.
	StatusExpired Status = "expired"
)

// maxSearchLen bounds the search text.
const maxSearchLen = 255

// Query selects certificates of all users, newest first.
type Query struct {
	// Search, when set, matches the username case-insensitively by substring,
	// or the serial number by prefix.
	Search string
	// Status, when set, matches only certificates in this state.
	Status Status
	// Page is the 1-based page of PageSize certificates.
	Page     int
	PageSize int
}

// Normalize trims the search text, then validates the query. The returned
// error is safe to show users.
func (q Query) Normalize() (Query, error) {
	q.Search = strings.TrimSpace(q.Search)
	switch {
	case len(q.Search) > maxSearchLen:
		return Query{}, fmt.Errorf("search must be at most %d characters", maxSearchLen)
	case q.Status != "" && q.Status != StatusActive && q.Status != StatusRevoked && q.Status != StatusExpired:
		return Query{}, errors.New(`status must be "active", "revoked" or "expired"`)
	case q.Page < 1:
		return Query{}, errors.New("page must be a positive integer")
	case q.PageSize < 1 || q.PageSize > MaxList:
		return Query{}, fmt.Errorf("page size must be between 1 and %d", MaxList)
	}
	return q, nil
}

// Revoked is a revoked certificate, as listed in the CRL.
type Revoked struct {
	Serial    string
	RevokedAt time.Time
}
